import { FC, memo } from 'react';
import styled from 'styled-components';
import { BasePanel } from '../atoms/BasePanel';

type Props = {
  action: (num: number) => void;
};

export const PanelScreen: FC<Props> = memo((props) => {
  const { action } = props;
  return (
    <div>
      <p>I have seen it...</p>
      <Panels>
        <BasePanel
          panelNum={1}
          action={() => {
            action(1);
          }}
        />
