          panelNum={24}
          action={() => {
            action(24);
          }}
        />
        <BasePanel
          panelNum={25}
          action={() => {
            action(25);
          }}
        />
      </Panels>
    </div>
  );
});

const Panels = styled.div`
  display: grid;
  grid-template-columns: 60px 60px 60px 60px 60px;
  gap: 0px;
  justify-content: center;
`;
